  mod_bhb_name: "Barras de vida de Behemoths",
  mod_bhb_text: "Una barra de vida grande para el Behemoth en la parte inferior de la pantalla, con el mismo estilo que la tuya y la vida exacta. Debajo, una barra azul muestra el escudo del Behemoth mientras lo tenga. En las Escaladas con dos Behemoths, cada uno tiene su propia barra.",
