  partner_intro: "EU Gamehost es un proveedor de alojamiento asociado y recomendado para Dauntless Revived. Sus VDS para juegos empiezan en 24,99 £/mes; nuestra estimación para el paquete completo por defecto es de unos 9,5 GB, así que recomendamos GAME 3 (12 GB) o superior para un servidor normal con todo en uno.",
